/**
 * GameScience house theme — clear, restrained, enterprise-ready.
 */

[data-theme="gamescience"] {
  --background: 1 0 0;
  --foreground: 0.206 0.039 265.5;

  --surface: 1 0 0;
  --surface-subtle: 0.967 0.006 255;
  --surface-raised: 1 0 0;
  --surface-overlay: 1 0 0;

  --border: 0.902 0.016 255;
  --border-strong: 0.623 0.044 256.8;
  --focus-ring: 0.545 0.215 262.7;

  --primary: 0.545 0.215 262.7;
  --primary-hover: 0.49 0.215 264.3;
  --primary-active: 0.423 0.181 265.6;
  --primary-foreground: 1 0 0;

  --secondary: 0.951 0.009 255;
  --secondary-hover: 0.902 0.016 255;
  --secondary-active: 0.837 0.022 253.4;
  --secondary-foreground: 0.271 0.059 265.2;

  --accent: 0.631 0.101 183.5;
  --accent-foreground: 1 0 0;

  --muted: 0.952 0.008 247.9;
  --muted-foreground: 0.514 0.036 256.8;

  --success: 0.568 0.121 157.8;
  --success-foreground: 1 0 0;
  --warning: 0.747 0.159 70.7;
  --warning-foreground: 0.284 0.063 53.9;
  --danger: 0.557 0.209 27.5;
  --danger-foreground: 1 0 0;
  --information: 0.57 0.152 248.4;
  --information-foreground: 1 0 0;

  --radius-control: 0.625rem;
  --radius-card: 0.875rem;
  --radius-panel: 1rem;
  --radius-overlay: 1.125rem;
  --radius-pill: 9999px;

  --border-width-control: 1px;
  --border-width-panel: 1px;

  --font-display: "Source Sans 3", "Segoe UI", sans-serif;
  --font-body: "Source Sans 3", "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;

  --font-weight-heading: 700;
  --font-weight-label: 600;
  --font-weight-body: 400;

  --tracking-heading: -0.015em;
  --tracking-label: 0.01em;
  --text-transform-label: none;

  --control-height-sm: 2rem;
  --control-height-md: 2.5rem;
  --control-height-lg: 3rem;

  --control-padding-inline-sm: 0.75rem;
  --control-padding-inline-md: 1rem;
  --control-padding-inline-lg: 1.25rem;

  --panel-padding-sm: 0.75rem;
  --panel-padding-md: 1.25rem;
  --panel-padding-lg: 1.75rem;

  --section-gap: 1.5rem;
  --content-max-width: 42rem;

  --shadow-control: 0 1px 2px rgb(15 23 42 / 0.05);
  --shadow-card: 0 8px 24px rgb(15 23 42 / 0.07);
  --shadow-overlay: 0 20px 48px rgb(15 23 42 / 0.14);
  --shadow-focus: 0 0 0 3px oklch(var(--focus-ring) / 0.3);

  --duration-fast: 120ms;
  --duration-standard: 200ms;
  --duration-emphasis: 320ms;

  --ease-standard: cubic-bezier(0.2, 0.8, 0.2, 1);
  --ease-emphasis: cubic-bezier(0.16, 1, 0.3, 1);

  --press-scale: 0.985;
  --hover-translate: -1px;

  --gs-shell-gradient: linear-gradient(
    160deg,
    oklch(0.984 0.003 247.9) 0%,
    oklch(0.958 0.01 255) 45%,
    oklch(0.938 0.014 265.9) 100%
  );

  --font-data: var(--font-mono);
  --glow-critical: var(--shadow-focus);
  --action-bar-pad-top: 1rem;
  --action-bar-safe-bottom: max(1rem, env(safe-area-inset-bottom));
  --action-bar-bleed: linear-gradient(
    to top,
    oklch(var(--background)) 35%,
    oklch(var(--background) / 0.85) 70%,
    transparent
  );
}

[data-theme="gamescience"] .gs-button[data-intent="secondary"] {
  box-shadow: none;
}

[data-theme="gamescience"] .gs-button[data-intent="secondary"]:focus-visible {
  box-shadow: var(--shadow-focus);
}

[data-theme="gamescience"] .gs-separator[data-treatment="hairline"] {
  background: oklch(var(--border));
}

[data-theme="gamescience"] .gs-sticky-action-bar {
  background-image: var(--action-bar-bleed);
}

/* Switch — off track resolves against the white thumb in the light theme */
[data-theme="gamescience"] .gs-switch {
  background: oklch(var(--border));
}

[data-theme="gamescience"] .gs-switch[data-state="checked"] {
  background: oklch(var(--primary));
}

[data-theme="gamescience"][data-context="shared-display"] {
  --background: 0.206 0.039 265.5;
  --foreground: 0.984 0.003 247.9;
  --surface: 0.237 0.041 265.8;
  --surface-subtle: 0.277 0.044 265.9;
  --surface-raised: 0.257 0.043 265.8;
  --surface-overlay: 0.237 0.041 265.8;
  --border: 0.381 0.042 259.8;
  --border-strong: 0.619 0.064 255.3;
  --muted: 0.298 0.041 266.1;
  --muted-foreground: 0.796 0.024 255.1;
  --gs-shell-gradient:
    radial-gradient(ellipse at 20% 0%, oklch(0.351 0.123 262.9 / 0.45), transparent 50%),
    linear-gradient(180deg, oklch(0.206 0.039 265.5), oklch(0.178 0.028 265.9));
}

/* Theme-owned shared-display grid (replaces former inline shell styles) */
[data-theme="gamescience"][data-context="shared-display"] .gs-shell {
  position: relative;
  isolation: isolate;
}

[data-theme="gamescience"][data-context="shared-display"] .gs-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  opacity: 0.4;
  background-image: radial-gradient(
    circle at 1px 1px,
    oklch(var(--border) / 0.35) 1px,
    transparent 0
  );
  background-size: 32px 32px;
}

[data-theme="gamescience"][data-context="shared-display"] .gs-shell > * {
  position: relative;
  z-index: 1;
}
